#include <iostream>

int main() {
    // Minh hoa co che doc phan doan bo dem cua cin.getline(s, 10)
    char s[10];
    std::cin.getline(s, 10);
    std::cout << s << "\n";

    // Trong C++17, neu cin.getline bi day bo dem (chua gap '\n'),
    // luong dat co failbit. Can clear() de doc tiep phan du trong bo dem.
    if (std::cin.fail()) {
        std::cin.clear();
    }
    std::cin.getline(s, 10);
    std::cout << s << "\n";

    // Vi du 2: Chuyen doi dinh dang ngay thang mm/dd/yy sang dd/mm/yy
    char US[9] = "05/01/99";
    char VN[9] = "  /  /  ";
    VN[0] = US[3];
    VN[1] = US[4]; // Ngay
    VN[2] = '/';
    VN[3] = US[0];
    VN[4] = US[1]; // Thang
    VN[5] = '/';
    VN[6] = US[6];
    VN[7] = US[7]; // Nam
    VN[8] = '\0';
    std::cout << VN << "\n";

    return 0;
}

#include <iostream>
#include <cstring>

int main() {
    // 1. strncpy voi con tro lech va bo sung '\0'
    char t[10] = "Steven";
    char s[20];
    std::strncpy(s, t, 5);
    s[5] = '\0'; // Bat buoc tu bo sung '\0' voi strncpy
    std::cout << s << " is young brother of " << t << "\n";

    // 2. Chuyen doi ngay thang dung strncpy va so hoc con tro
    char US[9] = "05/01/99";
    char VN[9] = "  /  /  ";
    std::strncpy(VN + 0, US + 3, 2); // Ngay
    std::strncpy(VN + 3, US + 0, 2); // Thang
    std::strncpy(VN + 6, US + 6, 2); // Nam
    VN[8] = '\0';
    std::cout << VN << "\n";

    // 3. strcat va strncat
    char a[100] = "Man";
    char b[10] = "toi";
    std::strcat(a, " va ");
    std::strcat(a, b);
    std::cout << a << "\n";

    char step[100];
    std::strncpy(step, t, 3);
    step[3] = '\0'; // "Ste"
    std::strcat(step, "p"); // "Step"
    std::cout << t << " goes " << step << " by " << step << "\n";

    char prefix[20] = "Nha ";
    char src[] = "vua chua";
    std::strncat(prefix, src + 4, 4); // Noi "chua"
    std::cout << prefix << "\n";

    return 0;
}
